*{box-sizing:border-box}
:root{--bg:#05070b;--panel:#0e131d;--panel2:#131b28;--line:#263246;--text:#edf2f7;--muted:#98a6b8;--gold:#d6b25e;--gold2:#f1d48c;--green:#28c7a5;--red:#ef6b78;--blue:#67a8ff}
html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:Inter,Segoe UI,Arial,sans-serif}
button,input,textarea,select{font:inherit}.app{min-height:100vh}.top{position:sticky;top:0;z-index:30;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 18px;background:rgba(5,7,11,.96);border-bottom:1px solid var(--line);backdrop-filter:blur(12px)}
.brand strong{display:block;color:var(--gold);font-size:24px;letter-spacing:.04em}.brand small{color:var(--muted)}
.status{font-size:12px;padding:7px 10px;border-radius:999px;background:#182234;color:#c7d2e0}.status.online{background:#07352d;color:#8ef5df}
.layout{display:grid;grid-template-columns:245px 1fr;min-height:calc(100vh - 65px)}.sidebar{border-right:1px solid var(--line);padding:14px;background:#080c13}.nav{display:grid;gap:6px}.nav button{display:flex;gap:10px;align-items:center;text-align:left;border:0;background:transparent;color:#cad4e0;padding:10px 12px;border-radius:10px;cursor:pointer}.nav button:hover,.nav button.active{background:var(--panel2);color:#fff}.nav .section{font-size:10px;text-transform:uppercase;letter-spacing:.14em;color:#718096;margin:14px 10px 5px}
main{padding:18px;max-width:1250px;width:100%;margin:0 auto}.hero{padding:20px;border:1px solid var(--line);background:linear-gradient(145deg,#121927,#0b1018);border-radius:18px;margin-bottom:14px}.hero h1{margin:0 0 5px;color:var(--gold2)}.hero p{margin:0;color:var(--muted)}
.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.card{border:1px solid var(--line);background:var(--panel);border-radius:14px;padding:14px}.card h3{margin:0 0 9px;color:var(--gold2)}.muted{color:var(--muted);font-size:13px}
.workspace{border:1px solid var(--line);background:var(--panel);border-radius:16px;padding:18px;min-height:420px}.workspace h2{margin-top:0;color:var(--gold2)}
label{display:block;font-size:12px;color:#b7c3d2;margin:8px 0 4px}input,textarea,select{width:100%;border:1px solid #2b3a50;background:#090e16;color:#f7fafc;padding:11px;border-radius:9px;outline:none}textarea{min-height:115px;resize:vertical}
.row{display:flex;gap:8px;flex-wrap:wrap}.btn{border:0;border-radius:9px;padding:10px 13px;font-weight:500;cursor:pointer}.primary{background:var(--gold);color:#18140b}.secondary{background:#243148;color:#f2f5f9}.success{background:var(--green);color:#04261f}.danger{background:#40202a;color:#ffd8de}.blue{background:#16375f;color:#dbeafe}
.output{white-space:pre-wrap;line-height:1.55;border:1px solid var(--line);background:#080d15;border-radius:11px;padding:13px;margin-top:12px;min-height:120px;overflow-wrap:anywhere}.chips{display:flex;gap:6px;flex-wrap:wrap}.chip{font-size:11px;border:1px solid var(--line);background:#121a27;border-radius:999px;padding:5px 8px}
.list{display:grid;gap:8px}.item{border:1px solid var(--line);background:#0b1018;border-radius:11px;padding:11px}.item strong{color:#fff}.item small{color:var(--muted)}.timer{font-size:54px;font-weight:500;text-align:center;color:var(--gold);letter-spacing:.04em}
.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.three{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
@media(max-width:850px){.layout{grid-template-columns:1fr}.sidebar{border-right:0;border-bottom:1px solid var(--line);overflow:auto}.nav{display:flex;overflow:auto}.nav .section{display:none}.nav button{white-space:nowrap}.grid,.three{grid-template-columns:1fr 1fr}}
@media(max-width:560px){.top{align-items:flex-start}.brand small{display:block}.grid,.two,.three{grid-template-columns:1fr}main{padding:10px}.workspace{padding:13px}.timer{font-size:42px}}

/* Studio router profiles â€” 3.5.2 */
.studio-router{margin:14px 0 12px;padding:13px;border:1px solid var(--line);background:#0b111b;border-radius:12px}
.mode-picker{display:grid;grid-template-columns:repeat(4,minmax(145px,1fr));gap:8px;margin-top:6px}
.mode-btn{border:1px solid var(--line);background:#121a27;color:#e7edf5;border-radius:10px;padding:10px 12px;cursor:pointer;text-align:left;display:flex;align-items:center;gap:7px;min-height:52px}
.mode-btn strong{font-size:14px}.mode-btn small{display:block;color:#92a1b4;font-size:10px;margin-left:auto}
.mode-btn:hover{border-color:#53657f;background:#172235}.mode-btn.active{border-color:var(--gold);box-shadow:0 0 0 1px var(--gold) inset;background:#221d11;color:#fff}
.studio-router-status{margin-top:8px;font-size:11px}
@media(max-width:900px){.mode-picker{grid-template-columns:1fr 1fr}.mode-btn small{margin-left:0}}
@media(max-width:520px){.mode-picker{grid-template-columns:1fr}}

