/* ================================================================
   LOGOS MASTER X 4.1.6 â€” CINEMATIC STARTUP
   Camada visual isolada: nÃ£o altera o layout da aplicaÃ§Ã£o.
   As cores seguem automaticamente o tema salvo.
   ================================================================ */
.cinematic-startup{
  --cin-primary:var(--startup-primary,var(--theme-primary,#2896ff));
  --cin-secondary:var(--startup-secondary,var(--theme-secondary,#f0b632));
  background:
    radial-gradient(ellipse at 50% 48%,color-mix(in srgb,var(--cin-primary) 13%,#02050a) 0%,#02050a 44%,#000 100%)!important;
  isolation:isolate;
  opacity:1;
  transition:opacity .58s cubic-bezier(.22,.7,.25,1),filter .58s ease!important;
}
.cinematic-startup.is-done{opacity:0!important;filter:brightness(1.16) blur(1.5px);pointer-events:none!important}
.cinematic-startup .mobile-loading-frame{z-index:3;overflow:visible;transform:scale(.965);opacity:.2;animation:logosStartupReveal 1.25s cubic-bezier(.18,.84,.24,1) forwards}
.cinematic-startup .mobile-loading-frame>img{position:relative;z-index:2;filter:saturate(.78) brightness(.62);animation:logosStartupImage 1.35s cubic-bezier(.2,.8,.2,1) forwards;will-change:filter,transform}
.cinematic-startup .startup-ambient{position:absolute;inset:0;z-index:1;overflow:hidden;pointer-events:none}
.cinematic-startup .startup-ambient::before{content:"";position:absolute;inset:-25%;background:conic-gradient(from 210deg at 50% 50%,transparent 0 23%,color-mix(in srgb,var(--cin-primary) 10%,transparent) 29%,transparent 36% 57%,color-mix(in srgb,var(--cin-secondary) 8%,transparent) 64%,transparent 71%);filter:blur(18px);animation:logosStartupTurn 7s linear infinite}
.cinematic-startup .startup-orbit{position:absolute;left:50%;top:50%;border:1px solid color-mix(in srgb,var(--cin-primary) 28%,transparent);border-radius:50%;transform:translate(-50%,-50%) scale(.55);opacity:0;box-shadow:0 0 26px color-mix(in srgb,var(--cin-primary) 18%,transparent),inset 0 0 18px color-mix(in srgb,var(--cin-secondary) 8%,transparent);animation:logosStartupOrbit 1.65s cubic-bezier(.16,.82,.24,1) forwards}
.cinematic-startup .startup-orbit-a{width:min(76vw,760px);aspect-ratio:1;animation-delay:.08s}
.cinematic-startup .startup-orbit-b{width:min(54vw,540px);aspect-ratio:1;border-color:color-mix(in srgb,var(--cin-secondary) 30%,transparent);animation-delay:.22s}
.cinematic-startup .startup-ray{position:absolute;left:50%;top:50%;width:min(100vw,1100px);height:2px;transform-origin:0 50%;opacity:0;background:linear-gradient(90deg,color-mix(in srgb,var(--cin-primary) 80%,white) 0%,color-mix(in srgb,var(--cin-primary) 26%,transparent) 22%,transparent 72%);filter:blur(.3px);animation:logosStartupRay 1.15s ease-out forwards}
.cinematic-startup .startup-ray-a{transform:rotate(-19deg);animation-delay:.22s}
.cinematic-startup .startup-ray-b{transform:rotate(161deg);background:linear-gradient(90deg,color-mix(in srgb,var(--cin-secondary) 74%,white),color-mix(in srgb,var(--cin-secondary) 22%,transparent) 24%,transparent 70%);animation-delay:.34s}
.cinematic-startup .startup-flare{position:absolute;left:50%;top:50%;width:22vmin;height:22vmin;border-radius:50%;transform:translate(-50%,-50%) scale(.25);opacity:0;background:radial-gradient(circle,color-mix(in srgb,var(--cin-primary) 75%,white) 0%,color-mix(in srgb,var(--cin-primary) 28%,transparent) 18%,color-mix(in srgb,var(--cin-secondary) 9%,transparent) 44%,transparent 72%);filter:blur(4px);animation:logosStartupFlare 1.45s ease-out forwards}
.cinematic-startup .startup-scan{position:absolute;left:-12%;right:-12%;height:18%;top:-22%;opacity:.0;background:linear-gradient(180deg,transparent,color-mix(in srgb,var(--cin-primary) 7%,transparent) 42%,color-mix(in srgb,var(--cin-primary) 26%,transparent) 50%,color-mix(in srgb,var(--cin-secondary) 8%,transparent) 58%,transparent);filter:blur(2px);animation:logosStartupScan 1.7s cubic-bezier(.25,.75,.2,1) .05s forwards}
.cinematic-startup .startup-image-glow{position:absolute;z-index:3;inset:4%;pointer-events:none;border-radius:5%;opacity:0;box-shadow:inset 0 0 46px color-mix(in srgb,var(--cin-primary) 15%,transparent),0 0 48px color-mix(in srgb,var(--cin-primary) 11%,transparent);animation:logosStartupImageGlow 1.45s ease-out .18s forwards}
.cinematic-startup .mobile-loading-live{z-index:5;opacity:.18;transform:scaleX(.92);animation:logosStartupBarReveal .8s ease-out .48s forwards}
.cinematic-startup .mobile-loading-live i{position:relative;overflow:visible}
.cinematic-startup .mobile-loading-live i::after{content:"";position:absolute;right:-7px;top:50%;width:15px;height:15px;border-radius:50%;transform:translateY(-50%);background:color-mix(in srgb,var(--cin-primary) 75%,white);box-shadow:0 0 14px var(--cin-primary),0 0 30px color-mix(in srgb,var(--cin-secondary) 45%,transparent);opacity:.82}
@keyframes logosStartupReveal{0%{opacity:.1;transform:scale(.93)}55%{opacity:1;transform:scale(1.012)}100%{opacity:1;transform:scale(1)}}
@keyframes logosStartupImage{0%{filter:saturate(.45) brightness(.42) contrast(1.08);transform:scale(1.02)}60%{filter:saturate(1.16) brightness(1.07) contrast(1.05);transform:scale(1)}100%{filter:saturate(1) brightness(1) contrast(1);transform:scale(1)}}
@keyframes logosStartupOrbit{0%{opacity:0;transform:translate(-50%,-50%) scale(.45)}42%{opacity:.8}100%{opacity:0;transform:translate(-50%,-50%) scale(1.18)}}
@keyframes logosStartupRay{0%{opacity:0;width:0}28%{opacity:.95}100%{opacity:0;width:min(100vw,1100px)}}
@keyframes logosStartupFlare{0%{opacity:0;transform:translate(-50%,-50%) scale(.18)}34%{opacity:.92}100%{opacity:0;transform:translate(-50%,-50%) scale(2.3)}}
@keyframes logosStartupScan{0%{top:-22%;opacity:0}18%{opacity:.72}82%{opacity:.34}100%{top:108%;opacity:0}}
@keyframes logosStartupImageGlow{0%{opacity:0}38%{opacity:1}100%{opacity:.18}}
@keyframes logosStartupBarReveal{to{opacity:1;transform:scaleX(1)}}
@keyframes logosStartupTurn{to{transform:rotate(360deg)}}
@media(max-width:760px){
  .cinematic-startup .startup-orbit-a{width:112vw}.cinematic-startup .startup-orbit-b{width:78vw}
