/* Hover universal dentro do Studio */
.studio-wizard button:not(:disabled){
  transition:transform .16s ease,filter .16s ease,border-color .16s ease,box-shadow .16s ease,background .16s ease!important;
}
.studio-wizard button:not(:disabled):hover{
  transform:translateY(-1px)!important;
  border-color:var(--v89-gold)!important;
  box-shadow:0 0 0 1px rgba(227,189,98,.18),0 0 18px rgba(227,189,98,.13)!important;
  color:var(--v89-gold-hi)!important;
}

/* Clique/seleÃ§Ã£o = amarelo preenchido, mesmo padrÃ£o em toda a pÃ¡gina */
.studio-wizard button.ui-clicked,
.studio-wizard button.active,
.studio-wizard button.selected,
.studio-wizard button[aria-selected="true"],
.studio-wizard button[aria-pressed="true"],
.studio-wizard input:checked + label{
  background:linear-gradient(180deg,var(--v89-gold-hi),var(--v89-gold))!important;
  color:var(--v89-ink)!important;
  border-color:#f6dc94!important;
  box-shadow:0 0 0 1px rgba(255,226,142,.28),0 0 18px rgba(227,189,98,.20)!important;
