/* ============================================================
   BÃBLIA X 5.4.34 â€” MÃ“DULO 4: VIAGEM VISUAL / ATLAS VIVO
   Estilo Ã©bano & ouro do modal de jornadas animadas.
   Anexado ao fim do CSS â€” nÃ£o toca no nÃºcleo.
   ============================================================ */

/* ---- BotÃ£o no rail de rotas (Mapas X) ---- */
.bx-v165-route-presets nav .bx-journey-rail-btn {
  flex: 0 0 auto;
  border: 1px solid rgba(228, 179, 61, .55);
  background: linear-gradient(180deg, rgba(228, 179, 61, .16), rgba(228, 179, 61, .05));
  color: #e4b33d;
  border-radius: 999px;
  padding: .4rem .9rem;
  font-size: .82rem;
  font-weight: 500;
  cursor: pointer;
  transition: background .18s, box-shadow .18s, transform .12s;
}
.bx-v165-route-presets nav .bx-journey-rail-btn:hover {
  background: linear-gradient(180deg, rgba(228, 179, 61, .3), rgba(228, 179, 61, .12));
  box-shadow: 0 0 0 1px rgba(228, 179, 61, .35), 0 2px 12px rgba(228, 179, 61, .25);
  transform: translateY(-1px);
}

/* ---- BotÃ£o no contexto do versÃ­culo ---- */
.bx-journey-ctx-btn {
  border: 1px solid rgba(228, 179, 61, .5);
  background: transparent;
  color: #e4b33d;
  border-radius: 999px;
  padding: .32rem .8rem;
  font-size: .78rem;
  font-weight: 500;
  cursor: pointer;
  transition: background .18s, box-shadow .18s;
}
.bx-journey-ctx-btn:hover { background: rgba(228, 179, 61, .14); box-shadow: 0 0 10px rgba(228, 179, 61, .25); }

/* ---- Modal ---- */
.bx-journey-modal {
  position: fixed;
  inset: 0;
  z-index: 100130;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.2rem;
  opacity: 0;
  pointer-events: none;
  transition: opacity .22s;
}
.bx-journey-modal.is-open { opacity: 1; pointer-events: auto; }
.bx-journey-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(4, 8, 13, .72);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
}
.bx-journey-sheet {
  position: relative;
  width: min(1180px, 100%);
  max-height: min(92vh, 900px);
  display: flex;
  flex-direction: column;
  background: linear-gradient(160deg, #0d151f, #0a0f16);
  border: 1px solid rgba(228, 179, 61, .4);
  border-radius: 18px;
  box-shadow: 0 24px 70px rgba(0, 0, 0, .65), 0 0 0 1px rgba(228, 179, 61, .12), 0 0 60px rgba(228, 179, 61, .12);
  overflow: hidden;
  transform: translateY(14px) scale(.985);
  transition: transform .26s cubic-bezier(.22, 1, .36, 1);
}
.bx-journey-modal.is-open .bx-journey-sheet { transform: none; }

/* ---- CabeÃ§alho ---- */
.bx-journey-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.05rem 1.25rem .7rem;
  border-bottom: 1px solid rgba(228, 179, 61, .18);
  background: linear-gradient(180deg, rgba(228, 179, 61, .07), transparent);
}
.bx-journey-eyebrow {
  display: block;
  font-size: .64rem;
  letter-spacing: .16em;
  color: #e4b33d;
  opacity: .85;
  font-weight: 500;
  margin-bottom: .2rem;
}
.bx-journey-head h3 {
  margin: 0;
  font-size: 1.28rem;
  color: #f6e9c9;
  line-height: 1.2;
}
.bx-journey-head p { margin: .2rem 0 0; font-size: .82rem; color: #9fb0bf; }
.bx-journey-head-actions { display: flex; gap: .5rem; align-items: center; flex: 0 0 auto; }
.bx-journey-dossier { flex: 0 0 auto; }
.bx-journey-close {
  width: 34px; height: 34px;
  border-radius: 50%;
  border: 1px solid rgba(228, 179, 61, .35);
  background: transparent;
  color: #e4b33d;
  font-size: 1.15rem;
  line-height: 1;
  cursor: pointer;
  transition: background .15s, transform .12s;
}
.bx-journey-close:hover { background: rgba(228, 179, 61, .16); transform: rotate(90deg); }

/* ---- Seletor de jornadas ---- */
.bx-journey-picker {
  display: flex;
  gap: .45rem;
  overflow-x: auto;
  padding: .75rem 1.25rem;
  border-bottom: 1px solid rgba(228, 179, 61, .14);
  scrollbar-width: thin;
  scrollbar-color: rgba(228, 179, 61, .4) transparent;
}
.bx-journey-picker::-webkit-scrollbar { height: 6px; }
.bx-journey-picker::-webkit-scrollbar-thumb { background: rgba(228, 179, 61, .35); border-radius: 99px; }
.bx-journey-chip {
  flex: 0 0 auto;
  border: 1px solid rgba(228, 179, 61, .3);
  background: rgba(228, 179, 61, .05);
  color: #cdd8e2;
  border-radius: 999px;
  padding: .38rem .85rem;
  font-size: .8rem;
  cursor: pointer;
  transition: background .16s, color .16s, border-color .16s, box-shadow .16s;
}
.bx-journey-chip:hover { border-color: rgba(228, 179, 61, .6); color: #f6e9c9; }
.bx-journey-chip.active {
  background: linear-gradient(180deg, #e4b33d, #c9982a);
  color: #141008;
  border-color: #f2d27e;
  font-weight: 500;
  box-shadow: 0 2px 14px rgba(228, 179, 61, .35);
}
.bx-journey-chip { max-width: 168px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.bx-journey-picker.is-embedded { display: none; }

/* ---- Corpo ---- */
.bx-journey-main {
  display: grid;
  grid-template-columns: minmax(0, 1.55fr) minmax(0, 1fr);
  gap: .9rem;
  padding: .9rem 1.25rem 1rem;
  min-height: 0;
  overflow: auto;
}
.bx-journey-mapcol { display: flex; flex-direction: column; gap: .55rem; min-width: 0; }
.bx-journey-mapbox {
  position: relative;
  width: 100%;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid rgba(228, 179, 61, .25);
  box-shadow: inset 0 0 40px rgba(0, 0, 0, .5), 0 0 0 1px rgba(0, 0, 0, .4);
  background: #080d15;
}
.bx-journey-mapbox .jr-map { display: block; width: 100%; height: auto; }
.bx-journey-modal.is-loading .bx-journey-mapbox { opacity: .55; transition: opacity .15s; }
.bx-journey-mapbox::after {
  content: "";
  position: absolute; inset: 0;
  pointer-events: none;
  border-radius: 12px;
  box-shadow: inset 0 0 0 1px rgba(228, 179, 61, .12);
}
/* Controles de zoom e tela cheia no mapa */
.bx-journey-zoomctl{position:absolute;top:10px;left:10px;z-index:3;display:flex;flex-direction:column;gap:6px}
.bx-journey-zbtn{width:32px;height:32px;border-radius:9px;border:1px solid rgba(228,179,61,.5);background:rgba(8,13,21,.84);color:#f0d47a;font-size:19px;line-height:1;display:grid;place-items:center;cursor:pointer;backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);transition:background .15s,box-shadow .15s}
.bx-journey-zbtn:hover{background:rgba(22,34,50,.96);box-shadow:0 0 12px rgba(228,179,61,.35)}
.bx-journey-zpct{min-width:32px;height:22px;display:grid;place-items:center;border-radius:7px;border:1px solid rgba(228,179,61,.3);background:rgba(8,13,21,.7);color:#f0d47a;font-size:10px;font-weight:500;letter-spacing:.2px;padding:0 4px}
.bx-journey-fs{position:absolute;top:10px;right:10px;z-index:3;width:34px;height:34px;border-radius:9px;border:1px solid rgba(228,179,61,.5);background:rgba(8,13,21,.84);color:#f0d47a;font-size:16px;display:grid;place-items:center;cursor:pointer;backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);transition:background .15s,box-shadow .15s}
.bx-journey-fs:hover{background:rgba(22,34,50,.96);box-shadow:0 0 12px rgba(228,179,61,.35)}
.bx-journey-mapbox:fullscreen,.bx-journey-mapbox.is-fs{position:fixed;inset:0;z-index:100200;width:100vw;height:100dvh;border-radius:0;background:#060a10}
