/* Seletor de jornada acoplado no rodapÃ© */
.bx-journey-jsel{flex:0 1 auto;min-width:0;max-width:220px;border:1px solid rgba(228,179,61,.4);background:#0d151f;color:#f6e9c9;border-radius:8px;padding:.3rem .5rem;font-size:.76rem;cursor:pointer}

/* ---- Elementos do mapa SVG ---- */
.jr-map .jr-sea { fill: rgba(18, 42, 66, .55); stroke: rgba(90, 140, 185, .28); stroke-width: .7; }
.jr-map .jr-river { fill: none; stroke: rgba(90, 140, 185, .4); stroke-width: 1; stroke-linecap: round; }
.jr-map .jr-region {
  fill: rgba(228, 179, 61, .4);
  font-size: 7px;
  letter-spacing: .18em;
  font-weight: 500;
  text-anchor: middle;
  dominant-baseline: central;
}
.jr-map .jr-grid { stroke: rgba(228, 179, 61, .06); stroke-width: .5; }
.jr-map .jr-route-base {
  fill: none;
  stroke: rgba(228, 179, 61, .35);
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-dasharray: 1 7;
  stroke-dashoffset: 0;
}
.jr-map .jr-route-glow {
  fill: none;
  stroke: #ffe9ad;
  stroke-width: 2.6;
  stroke-linecap: round;
  filter: drop-shadow(0 0 5px rgba(255, 222, 140, .9)) drop-shadow(0 0 14px rgba(228, 179, 61, .5));
}
.jr-map .jr-halo {
  transform-box: fill-box;
  transform-origin: center;
  animation: bxJvHalo 2.2s ease-out infinite;
}
.jr-map .jr-dot {
  fill: #fff4d6;
  stroke: #e4b33d;
  stroke-width: 2;
  transform-box: fill-box;
  transform-origin: center;
  filter: drop-shadow(0 0 4px rgba(255, 230, 160, 1));
}
.jr-map .jr-marker { cursor: pointer; transition: opacity .2s; }
.jr-map .jr-marker circle { fill: #0d141d; stroke: rgba(228, 179, 61, .55); stroke-width: 1.4; transition: all .25s; }
.jr-map .jr-marker text {
  fill: #cdd8e2;
  font-size: 8px;
  font-weight: 500;
  text-anchor: middle;
  dominant-baseline: central;
  transition: fill .25s;
}
.jr-map .jr-marker.is-start circle { fill: #e4b33d; stroke: #f2d27e; }
.jr-map .jr-marker.is-start text { fill: #141008; }
.jr-map .jr-marker.is-done circle { fill: #c9982a; stroke: #f2d27e; }
.jr-map .jr-marker.is-done text { fill: #141008; }
.jr-map .jr-marker.is-active circle {
  fill: #ffe9ad;
  stroke: #fff;
  stroke-width: 2.2;
  animation: bxJvPop .5s cubic-bezier(.22, 1.4, .36, 1);
}
.jr-map .jr-marker.is-active text { fill: #141008; font-size: 9px; }
.jr-map .jr-marker.is-next circle { fill: #0d141d; stroke: rgba(228, 179, 61, .9); stroke-width: 1.8; stroke-dasharray: 3 2; }
.jr-map .jr-marker:hover circle { stroke: #ffe9ad; }

/* ---- Progresso ---- */
.bx-journey-progress { display: flex; flex-direction: column; gap: .3rem; }
.bx-journey-progress > span { font-size: .72rem; color: #9fb0bf; letter-spacing: .02em; }
.bx-journey-progress-bar {
  height: 6px;
  border-radius: 99px;
  background: rgba(228, 179, 61, .14);
  overflow: hidden;
  border: 1px solid rgba(228, 179, 61, .2);
}
.bx-journey-progress-bar i {
  display: block;
  height: 100%;
  width: 0;
  border-radius: 99px;
  background: linear-gradient(90deg, #c9982a, #ffe9ad, #e4b33d);
  box-shadow: 0 0 8px rgba(228, 179, 61, .7);
  transition: width .15s linear;
}

/* ---- Legenda ---- */
.bx-journey-legend { display: flex; flex-wrap: wrap; gap: .55rem .8rem; }
.jr-lg-dot { display: inline-flex; align-items: center; gap: .32rem; font-size: .7rem; color: #9fb0bf; }
.jr-lg-dot::before {
  content: "";
  width: 9px; height: 9px;
  border-radius: 50%;
  background: #0d141d;
  border: 1px solid rgba(228, 179, 61, .55);
}
.jr-lg-dot.is-start::before { background: #e4b33d; border-color: #f2d27e; }
.jr-lg-dot.is-done::before { background: #c9982a; border-color: #f2d27e; }
.jr-lg-dot.is-active::before { background: #ffe9ad; border-color: #fff; }
.jr-lg-dot.is-next::before { background: transparent; border-style: dashed; }

/* ---- Trilho de fases (arco narrativo) ---- */
.bx-journey-side { display: flex; flex-direction: column; gap: .7rem; min-width: 0; min-height: 0; }
.bx-journey-arc {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: .3rem;
  padding: .55rem .2rem .3rem 1.55rem;
  border: 1px solid rgba(228, 179, 61, .16);
  border-radius: 12px;
  background: rgba(228, 179, 61, .035);
}
.bx-journey-arc::before {
  content: "";
  position: absolute;
  left: .72rem; top: .9rem; bottom: .9rem;
  width: 2px;
  border-radius: 99px;
  background: linear-gradient(180deg, rgba(228, 179, 61, .12), rgba(228, 179, 61, .5));
}
.bx-journey-phase {
  position: relative;
  display: flex;
  gap: .6rem;
  align-items: center;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  color: #9fb0bf;
  padding: .4rem .5rem;
  border-radius: 9px;
  cursor: pointer;
  transition: background .16s, color .16s;
}
.bx-journey-phase:hover { background: rgba(228, 179, 61, .09); color: #f6e9c9; }
.bx-journey-phase-dot {
  flex: 0 0 12px;
  width: 12px; height: 12px;
  border-radius: 50%;
  border: 2px solid rgba(228, 179, 61, .5);
  background: #0d151f;
  transition: all .2s;
}
.bx-journey-phase b { display: block; font-size: .8rem; font-weight: 500; color: inherit; }
.bx-journey-phase small { display: block; font-size: .66rem; color: #73818f; margin-top: .05rem; }
.bx-journey-phase.is-done { color: #d8bd7a; }
.bx-journey-phase.is-done .bx-journey-phase-dot { background: #c9982a; border-color: #f2d27e; }
.bx-journey-phase.is-active { color: #ffe9ad; background: rgba(228, 179, 61, .1); }
.bx-journey-phase.is-active .bx-journey-phase-dot {
  background: #ffe9ad;
  border-color: #fff;
  box-shadow: 0 0 0 4px rgba(228, 179, 61, .25), 0 0 12px rgba(228, 179, 61, .7);
}
.bx-journey-arc-note { font-size: .66rem; color: #73818f; padding: .2rem .5rem 0; }

/* ---- Card da parada ---- */
.bx-journey-card {
  border: 1px solid rgba(228, 179, 61, .25);
  border-radius: 12px;
  padding: .9rem 1rem 1rem;
  background: linear-gradient(165deg, rgba(228, 179, 61, .09), rgba(228, 179, 61, .02));
  box-shadow: 0 6px 22px rgba(0, 0, 0, .35);
  min-height: 0;
  animation: bxJvCardIn .32s cubic-bezier(.22, 1, .36, 1);
}
.bx-journey-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .5rem;
  margin-bottom: .5rem;
}
.bx-journey-card-num {
  font-size: .66rem;
  font-weight: 500;
  letter-spacing: .12em;
  color: #141008;
  background: linear-gradient(180deg, #e4b33d, #c9982a);
  border-radius: 99px;
  padding: .16rem .6rem;
}
.bx-journey-card-phase { font-size: .68rem; color: #e4b33d; letter-spacing: .05em; text-transform: uppercase; font-weight: 500; }
.bx-journey-card h4 { margin: 0 0 .35rem; font-size: 1.05rem; color: #f6e9c9; }
.bx-journey-card p { margin: 0 0 .6rem; font-size: .8rem; color: #b7c3ce; line-height: 1.5; }
.bx-journey-card-refs { display: flex; flex-wrap: wrap; gap: .45rem; margin-bottom: .6rem; }
.bx-journey-card-actions { display: flex; flex-wrap: wrap; gap: .4rem; margin-bottom: .6rem; }
.bx-journey-card-actions .btn, .bx-journey-card-refs .btn { font-size: .74rem; padding: .36rem .7rem; }
.bx-journey-card-nav button {
  width: 100%;
  border: 1px dashed rgba(228, 179, 61, .4);
  background: transparent;
  color: #e4b33d;
  border-radius: 9px;
  padding: .4rem;
  font-size: .74rem;
  cursor: pointer;
  transition: background .15s, border-color .15s;
}
.bx-journey-card-nav button:hover { background: rgba(228, 179, 61, .1); border-color: rgba(228, 179, 61, .8); }

/* ---- RodapÃ© / controles ---- */
.bx-journey-foot {
  display: flex;
  align-items: center;
  gap: .5rem;
  padding: .7rem 1.25rem .85rem;
  border-top: 1px solid rgba(228, 179, 61, .14);
  background: rgba(228, 179, 61, .04);
}
.bx-journey-fbtn {
  flex: 0 0 auto;
  width: 38px; height: 38px;
  border-radius: 50%;
  border: 1px solid rgba(228, 179, 61, .4);
  background: rgba(228, 179, 61, .08);
  color: #f6e9c9;
  font-size: .95rem;
  cursor: pointer;
  transition: background .15s, box-shadow .15s, transform .12s;
}
.bx-journey-fbtn:hover { background: rgba(228, 179, 61, .2); box-shadow: 0 0 12px rgba(228, 179, 61, .3); }
.bx-journey-fbtn:active { transform: scale(.93); }
.bx-journey-fbtn.is-play {
  width: 46px; height: 46px;
  background: linear-gradient(180deg, #e4b33d, #c9982a);
  border-color: #f2d27e;
  color: #141008;
  font-weight: 500;
  box-shadow: 0 3px 16px rgba(228, 179, 61, .45);
}
.bx-journey-speed {
  flex: 0 0 auto;
  border: 1px solid rgba(228, 179, 61, .3);
  background: #0d151f;
  color: #f6e9c9;
  border-radius: 999px;
  padding: .3rem .6rem;
  font-size: .76rem;
  cursor: pointer;
}
.bx-journey-footspacer { flex: 1 1 auto; }

/* ---- AnimaÃ§Ã£o de corpo travado ---- */
body.bx-journey-lock { overflow: hidden; }

/* ---- Keyframes ---- */
@keyframes bxJvHalo {
  0% { opacity: .9; transform: scale(.55); }
  100% { opacity: 0; transform: scale(1.6); }
}
@keyframes bxJvPop {
  0% { transform: scale(.5); }
  100% { transform: scale(1); }
}
@keyframes bxJvCardIn {
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: none; }
}

/* ---- Responsivo ---- */
